style.css:
/* ???? GOOGLE CLASSROOM — PASTEL PINK ???? */

/* Fondo general */
body {
    background: #fff5f8 !important;
}

/* Barra superior */
header,
[role="banner"] {
    background: #f8c8dc !important;
}

/* Tarjetas de las clases */
div[role="main"] {
    background: #fff5f8 !important;
}

a[href*="/c/"] {
    border-radius: 18px !important;
}

/* Tarjetas */
div[role="listitem"] {
    border-radius: 18px !important;
    box-shadow: 0 3px 12px rgba(230, 160, 185, 0.18) !important;
}

/* Botones */
button {
    border-radius: 12px !important;
}

/* Enlaces */
a {
    color: #c46b91 !important;
}

/* Campos de texto */
input,
textarea {
    background: #fffafd !important;
    border: 1px solid #f3bfd3 !important;
    border-radius: 12px !important;
}

/* Menús */
[role="menu"],
[role="dialog"] {
    border-radius: 16px !important;
}

/* Efecto suave al pasar por las tarjetas */
div[role="listitem"]:hover {
    transform: translateY(-2px);
    transition: 0.2s ease;
}
